package com.google.javascript.jscomp;

import com.google.common.annotations.VisibleForTesting;
import com.google.common.base.Charsets;
import com.google.common.io.CharStreams;
import com.google.common.io.Files;
import com.google.javascript.jscomp.SourceFile;
import com.google.javascript.rhino.jstype.StaticSourceFile;
import java.io.*;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.Serializable;
import java.io.StringReader;
import java.math.*;
import java.nio.charset.Charset;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static com.google.javascript.jscomp.SourceFile.fromCode;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class SourceFile_getLineOffset_TriageGen2Test {

    @Test
    public void testGetLineOffset_validLines() {
        // Create a source file with specific content to control offsets
        // Line 1: "abc\n" (offset 0)
        // Line 2: "def\n" (offset 4)
        // Line 3: "ghi"   (offset 8)
        String code = "abc\ndef\nghi";
        SourceFile sourceFile = fromCode("test.js", code);

        assertEquals("Offset for line 1 should be 0", 0, sourceFile.getLineOffset(1));
        assertEquals("Offset for line 2 should be 4", 4, sourceFile.getLineOffset(2));
        assertEquals("Offset for line 3 should be 8", 8, sourceFile.getLineOffset(3));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetLineOffset_lowerBoundOutOfBounds() {
        // lineno < 1
        SourceFile sourceFile = fromCode("test.js", "content");
        sourceFile.getLineOffset(0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetLineOffset_negativeOutOfBounds() {
        // lineno < 1
        SourceFile sourceFile = fromCode("test.js", "content");
        sourceFile.getLineOffset(-5);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetLineOffset_upperBoundOutOfBounds() {
        // lineno > lineOffsets.length
        // One line of content results in lineOffsets.length = 1
        SourceFile sourceFile = fromCode("test.js", "content");
        sourceFile.getLineOffset(2);
    }

    @Test
    public void testGetLineOffset_lazyInitialization() {
        // This test ensures that the 'if (lineOffsets == null)' branch is covered
        // by calling the method for the first time.
        SourceFile sourceFile = fromCode("test.js", "line1\nline2");

        // First call triggers findLineOffsets()
        int offset1 = sourceFile.getLineOffset(1);
        assertEquals(0, offset1);

        // Second call uses cached lineOffsets
        int offset2 = sourceFile.getLineOffset(2);
        assertEquals(6, offset2);
    }
}
